System.register("chunks:///_virtual/StoryData.ts",["cc"],(function(e){var t;return{setters:[function(e){t=e.cclegacy}],execute:function(){t._RF.push({},"fbeb9RKfeNKdJPdFpvk9LGO","StoryData",void 0);e("CH1_OPENING_BLACK",["风猛地灌进我的耳朵。","不是崖壁在往上——","是我在往下掉。","玉笛还在手里，我攥得指节发白。","水面在瞳孔里放大。","砰（落水声）。","……","不知道过去了多久。","一阵渐渐清晰的温暖将我热醒。"]),e("CH1_OPENING",[{speaker:"",text:"脸颊上一阵一阵的烘烤感，像有人把暖手宝贴在我脸上，还不肯拿开。",cg:"ch1_shore"},{speaker:"",text:"我睁开眼。先看见一片星空。"},{speaker:"伶伦",text:"……好看。",portrait:"伶伦"},{speaker:"",text:"我猛地坐起来。"},{speaker:"伶伦",text:"等等。我为什么躺在地上？",portrait:"伶伦"},{speaker:"",text:"身后是静得发黑的湖水，面前是一堆篝火，再往前，是密不透光的林子。"},{speaker:"伶伦",text:"冷静。先捋一下。",portrait:"伶伦"},{speaker:"伶伦",text:"吹了一段不认识的谱子。掉了下去。醒来躺在这里。",portrait:"伶伦"},{speaker:"伶伦",text:"……我穿越了？",portrait:"伶伦"},{speaker:"伶伦",text:"客服呢。",portrait:"伶伦"},{speaker:"",text:"没有人回答。"},{speaker:"伶伦",text:"行吧。那我自己来。",portrait:"伶伦"},{speaker:"",text:"（点击地面走动，或点击篝火）"}]),e("CH1_FIRE",[{speaker:"",text:"这火很怪。",cg:"ch1_shore"},{speaker:"",text:"柴枝整整齐齐垒着，粗的在下，细的在上，每一根长度都差不多。"},{speaker:"伶伦",text:"不是随手点的火。",portrait:"伶伦"},{speaker:"",text:"更像是，有人特意为我点的。"},{speaker:"",text:"我低头看了看自己的腰，忽然僵住。"},{speaker:"",text:"腰上挂着一支笛子。玉色的笛身，通体莹润。",cg:"ch1_flute"},{speaker:"",text:"一端系着细绳，吊着一块指甲盖大小的玉牌，上面刻着一个字。"},{speaker:"",text:"伶。"},{speaker:"伶伦",text:"这不是我的笛子。",portrait:"伶伦"},{speaker:"",text:"我的竹笛，在落水的时候已经被冲走了。"},{speaker:"伶伦",text:"……工艺不错。这个孔距，挺讲究。",portrait:"伶伦"},{speaker:"",text:"我把玉笛举到唇边，想试一个音。"},{speaker:"",text:"手伸到一半，停住了。"},{speaker:"奶奶",text:"他还说，不能乱吹。"},{speaker:"",text:"我把笛子拿开一寸，没有吹。"},{speaker:"伶伦",text:"这不是害怕。是谨慎。",portrait:"伶伦"}]),e("CH1_BEAR",[{speaker:"",text:"夜很静。",cg:"ch1_shore"},{speaker:"",text:"虫鸣，水声，风吹过树梢的沙沙声。"},{speaker:"",text:"这些声音之间，有一种隐隐约约的节奏。"},{speaker:"伶伦",text:"我这是干嘛。在这儿给林子打拍子。",portrait:"伶伦"},{speaker:"",text:"啪。"},{speaker:"",text:"像一根枯枝，被踩断了。"},{speaker:"伶伦",text:"……风吧。",portrait:"伶伦"},{speaker:"",text:"第二声响动。更近了。"},{speaker:"",text:"灌木猛地向两边分开。",cg:"ch1_bear"},{speaker:"",text:"一头棕熊。"},{speaker:"",text:"我的脑子一片空白。"},{speaker:"",text:"手速用不上。音准用不上。背过的几千首谱子，没有一样能挡住一头熊。"},{speaker:"",text:"熊低吼了一声。很低，很粗，尾音里带着一丝颤抖。"},{speaker:"",text:"那不是饥饿，是惊惧。"},{speaker:"",text:"对它来说，我才是闯进来的那个。"},{speaker:"",text:"一个很久以前的声音，忽然从记忆深处冒了出来。"},{speaker:"爷爷",text:"笛子不是用来炫技的。吹之前，先想清楚，你是在对谁说话。"},{speaker:"伶伦",text:"对谁说话。",portrait:"伶伦"},{speaker:"",text:"我握住了玉笛。"},{speaker:"伶伦",text:"不能吹到第七小节。",portrait:"伶伦"},{speaker:"",text:"熊已经冲到了三步之内。"},{speaker:"",text:"我把玉笛举到唇边。"}]),e("CH1_ENDING",[{speaker:"",text:"第一个音落下。清，轻，像是有人在夜里点亮了一盏很小的灯。",cg:"ch1_play"},{speaker:"",text:"笛孔里飘出一点光。淡蓝色，像一粒被风吹起来的萤火。"},{speaker:"",text:"接着是第二点，第三点。它们在空中舒展开，变成一对薄得几乎透明的翅膀。"},{speaker:"",text:"蝴蝶。",cg:"ch1_butterfly"},{speaker:"",text:"一只，两只，越来越多。绕着我的笛声转了一圈，齐齐朝熊飞去。"},{speaker:"",text:"最前面那只，轻轻落在熊的鼻尖上。像一滴水融进水里。"},{speaker:"",text:"熊的动作彻底停住了。"},{speaker:"",text:"那声低吼，慢慢，慢慢地沉了下去。"},{speaker:"",text:"它看了我很久。然后转过身，一步一步走回密林。"},{speaker:"",text:"灌木重新合拢，棕红色的影子消失在黑暗里。"},{speaker:"",text:"我腿一软，一屁股坐在了地上。",cg:"ch1_shore"},{speaker:"",text:"玉牌在火光里，轻轻晃了一下。"},{speaker:"伶伦",text:"刚才吹笛的时候……我没有想过任何人的评价。",portrait:"伶伦"},{speaker:"",text:"这是我吹了十几年笛子，第一次。",cg:"ch1_dawn"}]),e("CH1_CONVOY",[{speaker:"",text:"我盘坐在火堆旁，想了很久。",cg:"ch1_dawn"},{speaker:"",text:"穿越这件事，我已经接受了。可接受之后呢？"},{speaker:"",text:"我在哪个朝代，这个世界有没有人说中文，这支玉笛什么来头。"},{speaker:"",text:"每一个问题后面，都跟着一个更大的问题。"},{speaker:"伶伦",text:"算了。想不通的事，先放着。",portrait:"伶伦"},{speaker:"",text:"我往后一仰，躺在沙石上，双手枕在脑后。"},{speaker:"",text:"月亮已经升得很高，白得像一张洗干净的纸。"},{speaker:"",text:"我刚眯上眼，就听见了声音。"},{speaker:"",text:"很远。被林子滤过好几层。"},{speaker:"",text:"尖的、脆的声音大多被树叶吃掉了，只剩下闷闷的、低沉的响动。"},{speaker:"",text:"接着是一声拉长的、撕裂般的呼喊。"},{speaker:"",text:"然后有什么东西重重倒下。"},{speaker:"",text:"我几乎是从地上弹起来的。"},{speaker:"伶伦",text:"又来了？那头熊？",portrait:"伶伦"},{speaker:"",text:"我飞快地扫了一圈四周。篝火还在烧，湖面黑沉沉的，林子边缘静悄悄的。"},{speaker:"",text:"可那些声音还在继续，隔着至少几百米，夹着一声接一声的惨叫。"},{speaker:"伶伦",text:"……不是动物的叫声。",portrait:"伶伦"},{speaker:"",text:"按理说，我应该躲起来。一个刚穿越过来、什么都不清楚的人，最聪明的做法是蹲在火边等天亮。"},{speaker:"",text:"可我偏偏站着没动。"},{speaker:"伶伦",text:"……该不会是刚才那头熊吧。",portrait:"伶伦"},{speaker:"",text:"它走回林子的方向，和声音传来的方向，好像是同一个。"},{speaker:"",text:"我低头，摸了摸腰间的玉笛。"},{speaker:"伶伦",text:"要是真是它，我倒是有办法。",portrait:"伶伦"},{speaker:"",text:"这个想法让我自己都怔了一下。"},{speaker:"",text:"几个小时前，我还被那头熊吓得连腿都迈不开。"},{speaker:"",text:"我把玉笛握在手里，朝着声音的方向，迈开了步子。"},{speaker:"",text:"我走得很快，没有回头。"},{speaker:"",text:"林子里比我想的难走。"},{speaker:"",text:"落叶厚得没过脚踝，低垂的树枝时不时抽在脸上。"},{speaker:"",text:"听音辨位，是视唱练耳课最基础的内容。"},{speaker:"",text:"我试着把耳朵打开。"},{speaker:"",text:"近处是树叶，远处是风，更远处是一阵一阵的闷响。"},{speaker:"",text:"快要走出林子的时候，前方传来一串清脆的撞击声。"},{speaker:"",text:"尖，亮，带着金属特有的泛音。"},{speaker:"伶伦",text:"……兵器。",portrait:"伶伦"},{speaker:"",text:"我猫着腰，藏在一丛灌木后面，拨开枝叶。",cg:"ch2_convoy"},{speaker:"",text:"一条被踩得很实的土路，从林子中间穿过。"},{speaker:"",text:"路上停着一长串马车，十几辆，都堆着用粗麻布盖着的货物。"},{speaker:"",text:"有两辆翻倒在路边，麻袋裂开，露出金黄色的粮食。"},{speaker:"",text:"地上躺着人。"},{speaker:"",text:"离我最近的那个，是个年轻士兵。"},{speaker:"",text:"脸朝上，眼睛睁着，直直地望着天。"},{speaker:"",text:"他的胸口有一道很深的口子。"},{speaker:"",text:"我大脑空白了一秒。"},{speaker:"",text:"然后那股腥味，才像一堵墙一样撞了过来。"},{speaker:"",text:"铁锈，泥土，还有一种甜腻腻的、令人作呕的味道。"},{speaker:"",text:"我的胃猛地一缩。"},{speaker:"伶伦",text:"呜——",portrait:"伶伦"},{speaker:"",text:"我拼命用手捂住嘴。"},{speaker:"",text:"酸水涌上来，眼泪一下子冒了出来。"},{speaker:"",text:"死了。"},{speaker:"",text:"那个人，死了。"},{speaker:"",text:"不是电影，不是游戏，不是随时可以关掉的东西。"},{speaker:"",text:"他就在十几步之外，睁着眼睛，一动不动。"},{speaker:"",text:"我的手开始发抖。"},{speaker:"",text:"先是指尖，然后是整条手臂，最后连牙齿都在打颤。"},{speaker:"伶伦",text:"冷静……冷静……",portrait:"伶伦"},{speaker:"",text:"可「冷静」这两个字，像是被谁抽走了意思。"},{speaker:"",text:"我是个学生。上个礼拜还在为一次专业课的评语生闷气。"},{speaker:"",text:"我这辈子见过最大的事故，是路边的一场追尾。"},{speaker:"",text:"路中央，两拨人正在交手。"},{speaker:"",text:"一拨穿着浅褐色的皮甲，手里拿着青铜长矛和短剑，围成一个半圆，把几辆马车护在身后。"},{speaker:"云生",text:"都别慌！护住粮车！这是前线兄弟的命，也是黄帝的令！",portrait:"云生"},{speaker:"云生",text:"谁敢退一步，我云生第一个不饶他！",portrait:"云生"},{speaker:"",text:"另一拨，是一群黑衣人。"},{speaker:"",text:"一共七个。他们不列阵，散开着，像一群在夜里游走的影子。"},{speaker:"",text:"我的目光，落在其中一个人身上。"},{speaker:"",text:"是个女人。"},{speaker:"",text:"她脸上蒙着黑色的面纱，只露出一小截额头。",cg:"ch3_tianyu"},{speaker:"",text:"身形修长，腰身紧收。站着的时候，像一柄插在地上的细剑。"},{speaker:"",text:"她手里握着两把窄刀，刀柄上各挂着一串东西。"},{speaker:"",text:"挪动的时候，会发出清脆的声响。"},{speaker:"",text:"是风铃。"},{speaker:"",text:"玉质的风铃，一串三枚，一串四枚。"},{speaker:"伶伦",text:"……两串的音高，不一样。",portrait:"伶伦"},{speaker:"",text:"左边那串偏高，带着清冷；右边那串偏低，音色里有一丝温和。"},{speaker:"",text:"两串铃，一冷一暖，在厮杀声里，居然成了一段旋律。"},{speaker:"",text:"她动了。"},{speaker:"",text:"动作不快，但每一步，都踩在风铃响起的那一拍上。"},{speaker:"",text:"像是在跳一支很古老的舞。"},{speaker:"",text:"刀背一翻，在士兵的手腕和膝弯上各点了一下。"},{speaker:"",text:"士兵闷哼一声，跪倒下去。"},{speaker:"",text:"她没有低头看他一眼，已经转向下一个。"},{speaker:"",text:"一个，两个，三个。"},{speaker:"",text:"她所过之处，士兵一个接一个地倒下。"},{speaker:"",text:"我竟然没有看到血。"},{speaker:"",text:"可我很快就明白了，这并不是什么好事。"},{speaker:"",text:"因为她的身后，跟着另一个人。"},{speaker:"",text:"瘦高，像一根立在夜色里的竹竿。"},{speaker:"",text:"手里握着一把窄窄的短刃。"},{speaker:"",text:"他不急不躁，踩着女人走过的路，一步一步往前走。"},{speaker:"",text:"每到一个倒下的士兵身边，他就停一停，蹲下，短刃轻轻一划。"},{speaker:"",text:"很轻，很快，像是在割一块布。"},{speaker:"",text:"我的瞳孔猛地缩紧。"},{speaker:"",text:"不是喊声，不是风声，是极细极细的，皮肉被割开的那一下。"},{speaker:"",text:"我整个人，像被一根冰锥从头顶扎到了脚底。"},{speaker:"",text:"我想喊，嗓子里发不出声音。"},{speaker:"",text:"我想闭眼，眼皮像被钉住了。"},{speaker:"",text:"就在这时，我的耳朵在一片嗡鸣里，捕捉到一个很小的东西。"},{speaker:"",text:"风铃，漏了一拍。"},{speaker:"",text:"那串偏暖的铃，本该在她落脚时响起。"},{speaker:"",text:"可就在那个瘦高男人又一次蹲下去的瞬间，它没有响。"},{speaker:"高大男人",text:"蝠鳍。",portrait:"天黎"},{speaker:"",text:"一声低喝，像一块铁砸在地上。"},{speaker:"",text:"那是一个高大的男人，黑衣人里最高的一个。"},{speaker:"",text:"他比旁边的人高出一个头，肩宽背厚，像一头沉默的巨兽。"},{speaker:"",text:"他没有带面纱，脸完全露在火光里。"},{speaker:"",text:"不是书生那种温润的好看，是一种带着锋芒的、近乎凶悍的好看。"},{speaker:"",text:"眉毛浓黑，斜斜地压着一双眼睛，眼角有一点上挑。"},{speaker:"",text:"耳边挂着一枚银色的耳环。"},{speaker:"高大男人",text:"……适可而止吧。",portrait:"天黎"},{speaker:"",text:"只有四个字。"},{speaker:"",text:"蝠鳍盯着他，看了很久。"},{speaker:"蝠鳍",text:"好，听头儿的。",portrait:"蝠鳍"},{speaker:"",text:"他转过身，经过那个士兵身边的时候，脚尖在他受伤的手臂上碾了一下。"},{speaker:"蝠鳍",text:"点火！",portrait:"蝠鳍"},{speaker:"云生",text:"拦住他们！",portrait:"云生"},{speaker:"",text:"两个黑衣人提着火把，朝最近的一辆粮车冲了过去。"},{speaker:"",text:"我的手攥得发白。"},{speaker:"",text:"理智告诉我：走。现在就走。"},{speaker:"",text:"可我的腿，像是被钉在了地上。"},{speaker:"",text:"我的目光，被另一样东西钉住了。"},{speaker:"",text:"在最后面的那辆马车底下，有什么东西动了一下。"},{speaker:"",text:"一小团黑影，缩在车轮和车板的缝隙之间。"},{speaker:"",text:"用一块破布蒙着头，只露出一双眼睛。"},{speaker:"",text:"那是一双很亮的眼睛。"},{speaker:"",text:"亮得不像在害怕，倒像是在看一场很有意思的热闹。"},{speaker:"",text:"就在这时，我听见一声脆响。"},{speaker:"",text:"是风铃。清冷的那一串，在极近的地方响了一下。"},{speaker:"",text:"我僵住了。"},{speaker:"",text:"缓缓地，我抬起头。"},{speaker:"",text:"那个蒙着黑色面纱的女子，不知什么时候，已经站在了灌木丛前。"},{speaker:"",text:"离我不到五步。"},{speaker:"",text:"她垂着眼，手里握着双刀。"},{speaker:"",text:"面纱上方的那双眼睛，在夜色里，沉得像两口深井。"},{speaker:"面纱女子",text:"出来。",portrait:"面纱女子"},{speaker:"",text:"她的声音很轻，很冷，像一片雪落在刀刃上。"}]),e("CH1_TIANYU",[{speaker:"",text:"我没有犹豫，立刻站了起来。",cg:"ch3_tianyu"},{speaker:"",text:"与其说是站起来的，实则腿先软了一下，又被我硬生生撑住。"},{speaker:"",text:"我慢慢把双手举过肩膀。"},{speaker:"",text:"手心全是汗，玉笛滑得几乎握不住。"},{speaker:"",text:"面纱女子站在我面前，隔着七八步。"},{speaker:"",text:"她的目光，落在我脸上。"},{speaker:"",text:"只一眼。"},{speaker:"",text:"她的身形，极轻微地顿了一下。"},{speaker:"面纱女子",text:"是你？",portrait:"面纱女子"},{speaker:"",text:"两个字，短促，几乎是气音。"},{speaker:"",text:"我没听清，也没听懂。"},{speaker:"",text:"那一瞬间，她眼里闪过一点说不清的东西。"},{speaker:"",text:"不是杀意，更像是意外。"},{speaker:"",text:"可那点意外，很快就消失了。"},{speaker:"面纱女子",text:"你是何人？从何处来？",portrait:"面纱女子"},{speaker:"",text:"她开口，声音冷而平，字字清晰。"},{speaker:"",text:"我听懂了。"},{speaker:"",text:"这件事，我才后知后觉地意识到：我一直听得懂。"},{speaker:"伶伦",text:"我……我叫林……",portrait:"伶伦"},{speaker:"蝠鳍",text:"喂！",portrait:"蝠鳍"},{speaker:"",text:"一声暴喝，像一块石头砸进我们之间。"},{speaker:"",text:"我下意识转头。"},{speaker:"",text:"十几步外，两个黑衣人正围着云生打。"},{speaker:"",text:"云生的身上，多了一层半透明的、泛着青光的东西。"},{speaker:"",text:"从肩背一直覆盖到手臂，一块一块，排得整整齐齐。"},{speaker:"",text:"像一整副龟甲。"},{speaker:"蝠鳍",text:"别磨蹭了！把那个不知道哪儿冒出来的家伙了结掉，回来帮忙！",portrait:"蝠鳍"},{speaker:"",text:"了结掉。"},{speaker:"",text:"我脑子里嗡的一声。"},{speaker:"",text:"面纱女子却没有立刻回答。"},{speaker:"",text:"她的目光仍停在我身上，冷静，带着审视。"},{speaker:"",text:"然后，她抬起了刀。"},{speaker:"",text:"我甚至没有看清她的动作。"},{speaker:"",text:"只觉得眼前一花，两道银白色的光已经交叉着扫了过来。"},{speaker:"",text:"风铃的声音骤然急促。"},{speaker:"",text:"我身体比脑子先动，往后一仰，重重摔在地上。"},{speaker:"",text:"刀光从我鼻尖前掠过。"},{speaker:"",text:"她没有砍向我的脖子，也没有刺向我的胸口。"},{speaker:"",text:"那两把刀的轨迹，都落在我的肩侧与腰间。"},{speaker:"",text:"是刀背。"},{speaker:"伶伦",text:"（我要死了。）",portrait:"伶伦"},{speaker:"",text:"我的手，下意识地攥紧了掌心里的东西。"},{speaker:"",text:"是玉笛。"},{speaker:"",text:"一头熊，被笛子吹出来的蝴蝶驯服。"},{speaker:"",text:"随便走走，便能遇到两帮人马厮杀。"},{speaker:"",text:"一整副龟甲，凭空出现，披在一个人的身上。"},{speaker:"",text:"这个世界，从一开始就不是我的世界。"},{speaker:"",text:"既然如此，上一次能做到的事，这一次也许——"},{speaker:"",text:"我把玉笛举到唇边，闭上了眼睛。"},{speaker:"",text:"我没有想音准，没有想换气，更没有去想有没有人在听。"},{speaker:"",text:"我只想着一件事："},{speaker:"伶伦",text:"别杀我。我不想死。",portrait:"伶伦"},{speaker:"",text:"第一个音，很快落了下来。"}]),e("CH1_TIANYU_END",[{speaker:"",text:"清，轻，却又带着一丝颤抖。",cg:"ch3_subdue"},{speaker:"",text:"像是在黑暗里伸出去的一只手。"},{speaker:"",text:"笛孔里飘出了第一点淡蓝色的光。"},{speaker:"",text:"刀刃，在离我肩膀一寸的地方，停住了。"},{speaker:"",text:"不是被谁挡住，是她自己停住的。"},{speaker:"",text:"一点，两点，三点。"},{speaker:"",text:"淡蓝色的光从玉笛里飞出来，在夜色里舒展成一对对薄如蝉翼的翅膀。"},{speaker:"",text:"越来越多，围着我旋转。"},{speaker:"",text:"然后，有风。"},{speaker:"",text:"不是林子里的风，也不是湖面上的风。"},{speaker:"",text:"那股风是从我身前，毫无征兆地，向四面八方散开的。"},{speaker:"",text:"带着一种说不出的清润，像春天的第一场雨，还没落下，就已经闻到了泥土的气息。"},{speaker:"",text:"风吹过火把，火焰低伏了一瞬。"},{speaker:"",text:"风吹过倒下的士兵，吹过翻倒的粮车。"},{speaker:"",text:"风吹过云生肩上的青色龟甲，龟甲上的纹路忽然乱了一下。"},{speaker:"",text:"最后，风吹到了面纱女子的脸上。"},{speaker:"",text:"她的瞳孔，猛地缩紧。"},{speaker:"",text:"笛声钻进她耳朵，像一根极细的丝线，轻轻一拉。"},{speaker:"",text:"把她脑子里所有的东西，一下子抽空了。"},{speaker:"",text:"杀意，戒备，犹豫。"},{speaker:"",text:"所有念头都消失得干干净净，只剩下一片白。"},{speaker:"",text:"当啷。"},{speaker:"",text:"当啷。"},{speaker:"",text:"两把刀先后从她手里滑落，砸在地上。"},{speaker:"",text:"风铃发出一串杂乱的脆响。"},{speaker:"",text:"她就那么站着，睁着眼睛，一动不动。"},{speaker:"",text:"像睡着了。"},{speaker:"",text:"清风吹过。"},{speaker:"",text:"那块黑色的面纱，被轻轻地挑了起来，飘落在地。",cg:"ch3_face"},{speaker:"",text:"银色的月光取代了面纱，落在雪一样白的皮肤上。"},{speaker:"",text:"我眼里，除了她，一切都失了颜色。"},{speaker:"",text:"火光是灰的，夜色是灰的，连那些让我腿软的血，也是灰的。"},{speaker:"",text:"我是学音乐的。别说写诗，语文成绩也只能算半吊子。"},{speaker:"",text:"可不知为什么，我脑子里冒出了几句："},{speaker:"",text:"素纱既落，月华如水。"},{speaker:"",text:"翩若惊鸿，冷若秋霜。"},{speaker:"",text:"肩若削成，腰如约素。"},{speaker:"",text:"延颈秀项，皓质呈露。"},{speaker:"",text:"肤如凝脂，眉如翠羽。"},{speaker:"",text:"紫发垂云，朱瞳映星。"},{speaker:"",text:"增之一分则太长，减之一分则太短。"},{speaker:"",text:"腰悬玉铃，立如寒剑。"},{speaker:"",text:"我的嘴，不知不觉张开了。"},{speaker:"",text:"像一个第一次见到雪的人。"},{speaker:"",text:"她缓缓回过神来。"},{speaker:"",text:"眨了眨眼，像是刚从一场很长的梦里醒来。"},{speaker:"",text:"她低头，检查自己的身体。"},{speaker:"",text:"没有伤，没有血，连一点擦痕都没有。"},{speaker:"",text:"她又抬头，看向我。"},{speaker:"",text:"我一只手撑着地，一只手举着玉笛，嘴巴微张，目光呆滞。"},{speaker:"",text:"直勾勾地，盯着她的脸。"},{speaker:"",text:"那目光里，没有挑衅，没有恐惧。"},{speaker:"",text:"只有一种近乎痴呆的、纯粹的惊叹。"},{speaker:"",text:"一股滚烫的东西，轰地一下，冲上了她的脸颊。"},{speaker:"面纱女子",text:"你做了什么？",portrait:"天羽"},{speaker:"",text:"她抓起离自己最近的那把刀，把刀尖遥遥指向我。"},{speaker:"",text:"声音又冷又硬，带着压不住的怒意。"},{speaker:"伶伦",text:"我……我没做什么……",portrait:"伶伦"},{speaker:"",text:"我的声音很小，还带着一点没回过神的结巴。"},{speaker:"伶伦",text:"我就是……吹了一下笛子。",portrait:"伶伦"},{speaker:"面纱女子",text:"吹笛子？",portrait:"天羽"},{speaker:"",text:"她盯着我，眼里的红，像是要烧起来。"},{speaker:"",text:"我突然发现，自己的恐惧，竟然少了许多。"},{speaker:"",text:"面对这样一张脸，我连恐惧都变得迟钝了。"},{speaker:"伶伦",text:"你……你叫什么名字……",portrait:"伶伦"},{speaker:"",text:"这句话冒出来的时候，我自己都愣了一下。"},{speaker:"",text:"她没有回答。"},{speaker:"",text:"握刀的手，又紧了一分。"},{speaker:"高大男人",text:"撤！",portrait:"天黎"},{speaker:"",text:"一声沉喝，从战场中央传来。"},{speaker:"",text:"高大男人从云生的戈风里退出来，长刀拄在地上，胸口剧烈起伏。"},{speaker:"",text:"他的目光扫过燃烧的粮车，扫过倒下的黑衣人和士兵。"},{speaker:"",text:"最后，落在了她和我身上。"},{speaker:"高大男人",text:"粮车已经烧毁大半。再拖下去，对我们不利，撤。",portrait:"天黎"},{speaker:"",text:"黑衣人开始撤退。"},{speaker:"",text:"没有慌乱，没有拖沓。"},{speaker:"",text:"像来的时候一样，无声无息，一个接一个，没入夜色。"},{speaker:"",text:"只剩下面纱已经掉落的女子，还站在原地。"},{speaker:"",text:"她看了我一眼。"},{speaker:"",text:"我的脚边，躺着她遗落的另一把刀，只有一步之遥。"},{speaker:"",text:"她的目光，在那把刀上停了半息。"},{speaker:"",text:"要取回来，就得走过去。"},{speaker:"",text:"走到我面前，走进我伸手可及的距离，走进那支玉笛的范围里。"},{speaker:"",text:"她没有动。"},{speaker:"",text:"她握刀的手，在身侧，极其细微地收紧了一下。"},{speaker:"面纱女子",text:"这把刀，暂且放在你那里，替我保管好。",portrait:"天羽"},{speaker:"",text:"她的声音冷而平，一字一句。"},{speaker:"",text:"像是在宣布一件早就决定好的事。"},{speaker:"面纱女子",text:"如果你死了，那只能算我倒霉。",portrait:"天羽"},{speaker:"面纱女子",text:"如果没有……",portrait:"天羽"},{speaker:"面纱女子",text:"我会亲自回来取。",portrait:"天羽"},{speaker:"",text:"她顿了一下。"},{speaker:"面纱女子",text:"若有损坏，唯你是问。",portrait:"天羽"},{speaker:"",text:"说完，她再没有看我一眼。"},{speaker:"",text:"转过身，纵身一跃，身影像一片叶子，没入林子。"},{speaker:"",text:"风铃的声音，渐渐远了。"},{speaker:"",text:"我在原地坐了很久。",cg:"ch1_dawn"},{speaker:"",text:"四周，火还在烧。"},{speaker:"",text:"云生在指挥士兵扑火，有人在哀嚎，有人在抬伤员。"},{speaker:"",text:"没有人注意我，也没有人来问我是谁。"},{speaker:"",text:"我低下头，看着自己的手。"},{speaker:"",text:"掌心里，还是那支玉笛。"},{speaker:"",text:"腿边，一把窄窄的刀，刀柄上挂着一串玉铃。"},{speaker:"",text:"在夜风里，一下一下，轻轻地响。"},{speaker:"",text:"我伸手，把那把刀拾了起来。"},{speaker:"",text:"很轻。比我想象的要轻得多。"},{speaker:"",text:"我想起那张脸，想起她站在火光里，紫色的长发被风吹乱的样子。"},{speaker:"",text:"想起她说的最后那句话。"},{speaker:"伶伦",text:"替我保管……",portrait:"伶伦"},{speaker:"",text:"我挠了挠头，总觉得这话，听起来，哪里怪怪的。"},{speaker:"",text:"可我没有想明白。"},{speaker:"",text:"第一章 完"}]),e("CH1_EMPTY_HINT",{fire:[{speaker:"",text:"火还在烧着。"},{speaker:"",text:"但是什么都没有了。"}],convoy:[{speaker:"",text:"车队已经走远了。"},{speaker:"",text:"地上只剩下几道车辙。"}]});t._RF.pop()}}}));

